import Icon from 'flarum/common/components/Icon';

/**
 * A medalha do emblema no admin (o mesmo markup do fórum): ícone ou imagem
 * dentro do círculo da cor do tipo.
 */
export function medal(badge, size = 'small') {
  const imageUrl = badge.imageUrl && /^https?:\/\//i.test(badge.imageUrl) ? badge.imageUrl : null;
  return m("span", {
    className: `CanelaBadgeMedal CanelaBadgeMedal--${badge.type} CanelaBadgeMedal--${size}${imageUrl ? ' CanelaBadgeMedal--image' : ''}`
  }, imageUrl ? m("img", {
    className: "CanelaBadgeMedal-image",
    src: imageUrl,
    alt: "",
    loading: "lazy"
  }) : m(Icon, {
    name: badge.icon || 'fas fa-certificate',
    className: "CanelaBadgeMedal-icon"
  }));
}
flarum.reg.add('ramon-canela', 'admin/features/badgesAdmin/medal', { medal: medal, });